package local.skyfamily;
import android.graphics.*;import android.os.*;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.content.Context;import android.widget.*;import java.io.File;import java.util.*;import org.json.JSONObject;
public class LegacyDashActivity extends ExploreActivity {
 boolean resumed=false,hidden=false,revealGesture=false,touching=false;String currentTitle="",idleFailure="";final Handler focusClock=new Handler();final LinkedHashMap<View,Integer> chrome=new LinkedHashMap<>();final Runnable hideLater=()->enterFocus();
 @Override public void onCreate(Bundle state){super.onCreate(state);if(!prefs.contains("gallery.idle"))prefs.edit().putBoolean("gallery.idle",true).apply();}
 @Override void normalWindow(){if(!hidden)super.normalWindow();}
 @Override void page(String title){hidden=false;chrome.clear();focusClock.removeCallbacksAndMessages(null);currentTitle=title;super.page(title);if(sidebar!=null&&sidebar.getChildCount()>0){View old=sidebar.getChildAt(0);ViewGroup.LayoutParams size=old.getLayoutParams();sidebar.removeViewAt(0);ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.ic_sky);logo.setScaleType(ImageView.ScaleType.FIT_CENTER);logo.setPadding(dp(10),dp(6),dp(10),dp(6));logo.setContentDescription("legacydash / Home");logo.setOnClickListener(v->home());sidebar.addView(logo,0,size);}compactShell();scheduleFocus();}
 void compactShell(){boolean shortScreen=getResources().getConfiguration().screenHeightDp<420;if(shortScreen&&sidebar!=null){View parent=(View)sidebar.getParent();ViewGroup.LayoutParams size=parent.getLayoutParams();size.width=dp(56);parent.setLayoutParams(size);for(int i=1;i<sidebar.getChildCount();i++){View entry=sidebar.getChildAt(i);if(entry instanceof LinearLayout){LinearLayout item=(LinearLayout)entry;for(int n=0;n<item.getChildCount();n++)if(item.getChildAt(n) instanceof TextView)item.getChildAt(n).setVisibility(View.GONE);item.setPadding(0,dp(2),0,dp(2));item.getLayoutParams().height=dp(48);}}if(header!=null)header.setVisibility(View.GONE);}}
 @Override LinearLayout toolsBar(){LinearLayout row=super.toolsBar();if(getResources().getConfiguration().screenHeightDp<420)((View)row.getParent()).getLayoutParams().height=dp(48);return row;}
 @Override void home(){super.home();button("Apps",()->apps());}
 @Override void normalize(View view){super.normalize(view);if(view instanceof DestinationIcon){Paint ink=new Paint();ink.setColorFilter(new PorterDuffColorFilter(INK,PorterDuff.Mode.SRC_IN));if(view.getLayerType()!=View.LAYER_TYPE_SOFTWARE)view.setLayerType(View.LAYER_TYPE_SOFTWARE,ink);}}
 @Override void categoryIcons(View root){super.categoryIcons(root);coreIcons(root);}
 void coreIcons(View root){if(!(root instanceof ViewGroup))return;ViewGroup group=(ViewGroup)root;for(int i=0;i<group.getChildCount();i++){View child=group.getChildAt(i);if(child instanceof ControlIcon){int kind=CoreGlyph.kind(((ControlIcon)child).label);if(kind!=0){ViewGroup.LayoutParams size=child.getLayoutParams();group.removeViewAt(i);group.addView(new CoreGlyph(this,kind),i,size);}}else coreIcons(child);}}
 @Override void schoolNote(String id){super.schoolNote(id);if(id.equals(noteId)&&noteText!=null&&noteInk!=null){noteInk.bind(noteText);noteInk.writing=false;noteText.setVisibility(View.VISIBLE);noteInk.setVisibility(View.VISIBLE);noteInk.bringToFront();scheduleFocus();}}
 @Override void tool(LinearLayout row,String title,Runnable action){super.tool(row,title,()->{action.run();if((title.equals("Type")||title.equals("Ink"))&&!noteId.isEmpty()&&noteInk!=null&&noteText!=null){noteText.setVisibility(View.VISIBLE);noteInk.bind(noteText);noteInk.setVisibility(View.VISIBLE);noteInk.bringToFront();noteInk.writing=title.equals("Ink");if(noteInk.writing){InputMethodManager keyboard=(InputMethodManager)getSystemService(Context.INPUT_METHOD_SERVICE);if(keyboard!=null)keyboard.hideSoftInputFromWindow(noteText.getWindowToken(),0);}}scheduleFocus();});}
 @Override void openBook(JSONObject book){super.openBook(book);if(pdf!=null){updatePdfLabels(pdf);scheduleFocus();}}
 void updatePdfLabels(View root){if(root instanceof TextView){TextView text=(TextView)root;if(text.getText().toString().startsWith("Temporary PDF marks"))text.setText("Local annotation layer / original PDF unchanged. Pan navigates; Pen and Highlight draw.");}if(root instanceof ViewGroup){ViewGroup group=(ViewGroup)root;for(int i=0;i<group.getChildCount();i++)updatePdfLabels(group.getChildAt(i));}}
 @Override void santa(){openPublic("Santa tracker / official NORAD site","https://www.noradsanta.org/");focusClock.post(()->enterFocus());}
 boolean focusEligible(){return web!=null||pdf!=null||currentArt!=null||!noteId.isEmpty()||currentTitle.equals("Notes");}
 boolean keyboardVisible(){View decor=getWindow().getDecorView();Rect visible=new Rect();decor.getWindowVisibleDisplayFrame(visible);return decor.getHeight()-visible.bottom>dp(120);}
 void scheduleFocus(){focusClock.removeCallbacks(hideLater);if(resumed&&!hidden&&focusEligible())focusClock.postDelayed(hideLater,8000);}
 void hideView(View view){if(view!=null&&view.isShown()&&!chrome.containsKey(view)){chrome.put(view,view.getVisibility());view.setVisibility(View.GONE);}}
 void enterFocus(){if(!resumed||hidden||!focusEligible())return;if(touching||keyboardVisible()){scheduleFocus();return;}if(sidebar!=null&&sidebar.getParent() instanceof View)hideView((View)sidebar.getParent());hideView(header);if(pdf!=null){for(int i=0;i<pdf.getChildCount();i++){View child=pdf.getChildAt(i);if(child instanceof LinearLayout||child instanceof TextView)hideView(child);}}else if(body!=null&&body.isShown()){for(int i=0;i<body.getChildCount();i++){View child=body.getChildAt(i);if(!(child instanceof FrameLayout)&&!(child instanceof android.webkit.WebView)&&child!=currentArt)hideView(child);}}hidden=true;getWindow().addFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN);int flags=View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION;if(Build.VERSION.SDK_INT>=19)flags|=View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY;getWindow().getDecorView().setSystemUiVisibility(flags);}
 void reveal(){hidden=false;for(View view:chrome.keySet())view.setVisibility(chrome.get(view));chrome.clear();normalWindow();scheduleFocus();}
 @Override public boolean dispatchTouchEvent(MotionEvent event){int action=event.getActionMasked();if(action==MotionEvent.ACTION_DOWN){touching=true;if(hidden){revealGesture=true;reveal();}focusClock.removeCallbacks(hideLater);}if(revealGesture){if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL){revealGesture=false;touching=false;scheduleFocus();}return true;}boolean result=super.dispatchTouchEvent(event);if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL){touching=false;scheduleFocus();}return result;}
 @Override public boolean dispatchKeyEvent(android.view.KeyEvent event){scheduleFocus();return super.dispatchKeyEvent(event);}
 boolean uploadedPhotos(){File[] images=new File(getFilesDir(),"uploads").listFiles((dir,name)->name.endsWith(".image"));return images!=null&&images.length>0;}
 void idleError(String message){if(!message.equals(idleFailure)){idleFailure=message;toast(message);}armIdle();}
 @Override void armIdle(){idle.removeCallbacksAndMessages(null);if(!resumed||!atHome||prefs==null||!prefs.getBoolean("gallery.idle",false))return;long delay=Math.max(30000L,Math.min(3600000L,prefs.getInt("gallery.idle.seconds",120)*1000L));idle.postDelayed(()->{if(!resumed||!atHome)return;boolean local=prefs.getBoolean("gallery.local",false);if(local&&!uploadedPhotos()){idleError("Idle gallery unavailable / upload photos first");return;}if(!local&&token.isEmpty()){idleError("Idle gallery unavailable / reconnect Immich or select uploaded photos");return;}idleFailure="";startGallery(local);},delay);}
 @Override public void onConfigurationChanged(android.content.res.Configuration config){if(hidden)reveal();super.onConfigurationChanged(config);compactShell();scheduleFocus();}
 @Override public void onBackPressed(){if(hidden){reveal();return;}super.onBackPressed();}
 @Override protected void onResume(){super.onResume();resumed=true;armIdle();scheduleFocus();}
 @Override protected void onPause(){if(hidden)reveal();resumed=false;focusClock.removeCallbacksAndMessages(null);super.onPause();}
 @Override protected void onDestroy(){focusClock.removeCallbacksAndMessages(null);super.onDestroy();}
}
